25	/**
26	 * A simple Filament plugin to configure the panel via this package.
27	 */
28	class DigitalHubPlugin implements Plugin
29	{
30	    public static function make(): static
31	    {
32	        /** @var static $plugin */
33	        $plugin = app(static::class);
34	
35	        return $plugin;
36	    }
37	
38	    public function getId(): string
39	    {
40	        return 'digital-hub';
41	    }
42	
43	    public function register(Panel $panel): void
44	    {
45	        $panel
46	            ->plugin(MinimalTheme::make())
47	            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
48	            ->font('Open Sans')
49	            ->pages([
50	                Catalog::class,
51	                AssetManager::class,
52	                ManageGeneralSettings::class,
53	            ])
54	            // Voce "Impostazioni" nello user menu (dropdown del badge utente),
55	            // non in sidebar (la pagina ha shouldRegisterNavigation = false).
56	            // Visibile solo a chi può gestire le impostazioni.
57	            ->userMenuItems([
58	                Action::make('settings')
59	                    ->label('Impostazioni')
60	                    ->icon(Heroicon::OutlinedCog6Tooth)
61	                    ->url(fn (): string => ManageGeneralSettings::getUrl())
62	                    ->visible(fn (): bool => ManageGeneralSettings::canAccess()),
63	            ])
64	            // Immagine di sfondo nella schermata di login. Il path è gestito dalla
65	            // pagina Impostazioni (GeneralSettings); se non impostato non viene
66	            // iniettato nulla e resta lo sfondo di default. CSS scoped alla login.
67	            ->renderHook(
68	                PanelsRenderHook::HEAD_END,
69	                function (): string|HtmlString {
70	                    $settings = app(GeneralSettings::class);
71	
72	                    if (blank($settings->login_background_path)) {
73	                        return '';
74	                    }
75	
76	                    $url = Storage::disk('public')->url($settings->login_background_path);
77	                    $overlay = self::overlayRgba($settings->login_overlay_color, $settings->login_overlay_opacity);
78	
79	                    return new HtmlString(
80	                        '<style>
81	                            .fi-simple-layout {
82	                                background-image: linear-gradient(' . $overlay . ', ' . $overlay . '), url("' . e($url) . '");
83	                                background-size: cover;
84	                                background-position: center;
85	                                background-repeat: no-repeat;
86	                            }
87	                        </style>',
88	                    );
89	                },
90	                scopes: Login::class,
91	            )
92	            ->renderHook(
93	                PanelsRenderHook::SIMPLE_PAGE_START,
94	                fn () => '<div class="afh-login-wrapper">',
95	                scopes: Login::class,
96	            )
97	            ->renderHook(
98	                PanelsRenderHook::SIMPLE_PAGE_END,
99	                fn () => '</div>',
100	                scopes: Login::class,
101	
102	            )
103	            
104	            
105	            ;
106	
107	        $primaryColor = config('digital-hub.primary_color');
108	        if (is_string($primaryColor) && $primaryColor !== '') {
109	            /** @var array<int, string> $color */
110	            $color = \Filament\Support\Colors\Color::{$primaryColor};
111	            $panel
112	            ->colors([
113	                'primary' => $color,
114	            ]);
115	        }
116	
117	    }
118	
119	    public function boot(Panel $panel): void
120	    {
121	        Notifications::alignment(Alignment::Center);
122	
123	        Table::configureUsing(function (Table $table): Table {
124	            return $table->defaultPaginationPageOption(50);
125	        });
126	
127	        DigitalHubTableMacro::register();
128	
129	
130	    }
131	
132	    /**
133	     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
134	     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
135	     * impostazioni. Input non validi degradano a nero/opacità clampata.
136	     */
137	    private static function overlayRgba(string $hex, float $opacity): string
138	    {
139	        $hex = ltrim($hex, '#');
140	
141	        if (strlen($hex) === 3) {
142	            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
143	        }
144	
145	        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
146	            $hex = '000000';
147	        }
148	
149	        $r = (int) hexdec(substr($hex, 0, 2));
150	        $g = (int) hexdec(substr($hex, 2, 2));
151	        $b = (int) hexdec(substr($hex, 4, 2));
152	        $alpha = max(0.0, min(1.0, $opacity));
153	
154	        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
155	    }
156	
157	}
